def prompt(n: int) -> str:
    texto = P[n]
    for k, v in T.items():
        texto = texto.replace("{" + k + "}", v)
    texto = texto[0].upper() + texto[1:]
    return f"{BASE} {BONECO} {texto}" if "stick figure" in texto else f"{BASE} {texto}"


def cartao(n: int) -> bool:
    return P[n].startswith("{CARD}")
